modules.kdl:
pane_template name="topBar" borderless=true {
    plugin location="zellij:tab-bar"
}
pane_template name="bottomBar" borderless=true {
    plugin location="zellij:status-bar"
}
default_tab_template {
    topBar size=1
    children
    bottomBar size=1
}

pane_template name="editorPane" command="nvim" {
    args "--clean" "notes with spaces.md"
}
pane_template name="testPane" command="make" {
    args "test"
}

tab_template name="devTab" {
    topBar size=1
    children
    bottomBar size=1
}

projects.kdl:
devTab name="Dev" cwd="/work/alpha" focus=true {
    editorPane focus=true
    testPane
}

tab name="Review" cwd="/work/beta/docs" {
    editorPane focus=true
}
tab name="Test" cwd="/work/beta/service" focus=true {
    testPane focus=true
}
